"""Bounded original-byte verification of WaterSound selection and shore correction."""
from pathlib import Path
import hashlib,json,math,struct,sys
BASE=Path(__file__).resolve().parent.parent
sys.path.insert(0,str(BASE/'work/pydeps'))
import pefile
from capstone import Cs,CS_ARCH_X86,CS_MODE_32
target=Path(r'D:\SteamLibrary\steamapps\common\Townscaper\GameAssembly.dll')
data=target.read_bytes();pe=pefile.PE(data=data);base=pe.OPTIONAL_HEADER.ImageBase
md=Cs(CS_ARCH_X86,CS_MODE_32)
def decode(start,end):
    return list(md.disasm(data[pe.get_offset_from_rva(start):pe.get_offset_from_rva(end)],base+start))
def record(i):return {'va':hex(i.address),'bytes':i.bytes.hex(),'mnemonic':i.mnemonic,'operands':i.op_str}
specs=[(0x3f0ae0,0x3f0cc8,'WaterSound.Update complete function'),(0x8187c3,0x8190a3,'Sandbank stage2 triangle correction, accumulator flush and three-pass loop'),(0x673cc0,0x673dc9,'Vector3.Normalize magnitude threshold and zero branch'),(0x674430,0x674481,'Vector3.normalized wrapper'),(0x22e110,0x22e152,'Vector3 addition'),(0x22e1b0,0x22e1f2,'Vector3 subtraction'),(0x448850,0x44888a,'Three-way Vector3 cyclic rotation'),(0x674620,0x674665,'Vector3 inequality squared-distance threshold')]
specs.append((0x817cfd,0x8187c3,'Stage2 odd-vertex lift, strip directional collapse and diagonal rewrite'))
windows=[];byva={}
for start,end,label in specs:
    ins=decode(start,end);byva.update({i.address:i for i in ins})
    windows.append({'rva_start':hex(start),'rva_end_exclusive':hex(end),'label':label,'instructions':[record(i)for i in ins]})
for va,operand in [(0x103f0c0d,'xmm2, dword ptr [ebp - 0x28]'),(0x103f0c1c,'xmm1, dword ptr [ebp - 0x24]'),(0x103f0c2b,'xmm0, dword ptr [ebp - 0x20]')]:
    assert byva[va].mnemonic=='subss' and byva[va].op_str==operand
assert byva[0x10818956].op_str=='dword ptr [ebp - 0x34], 0'
assert byva[0x10818d7b].op_str=='0x10674430' and byva[0x10818dcf].op_str=='0x1022e1b0'
assert byva[0x10818e3d].mnemonic=='subss' and byva[0x10818ee5].op_str=='0x1022e110'
assert not any(i['mnemonic'].startswith('j') for w in windows if w['label'].startswith('Sandbank') for i in w['instructions']if 0x10818e06<=int(i['va'],16)<0x10818e90)
assert byva[0x10818a64].op_str=='0x1022e1b0' and byva[0x10818ac3].op_str=='0x10837090'
assert byva[0x10818bbe].op_str=='0x1022e110' and byva[0x10818c65].op_str=='0x1022e1b0'
assert byva[0x1081815b].op_str=='0x10673720'
assert [i.address for i in decode(0x817cfd,0x8187c3)if '0x4a8' in i.op_str]==[0x10818154]
assert byva[0x10818339].op_str=='0x108185fd' and byva[0x108186d0].op_str=='0x108187a5'
constants=[]
for va,label in [(0x111d3864,'WaterSound initial best distance squared float.MaxValue'),(0x111e1e48,'shore target horizontal signed distance'),(0x111f1658,'shore correction relaxation ratio'),(0x111e7950,'Vector3.Normalize minimum magnitude'),(0x111d3a88,'Vector3 inequality minimum squared distance')]:
    off=pe.get_offset_from_rva(va-base);raw=data[off:off+4]
    constants.append({'va':hex(va),'meaning':label,'bytes':raw.hex(),'float32':struct.unpack('<f',raw)[0]})
assert constants[0]['bytes']=='ffff7f7f' and constants[1]['bytes']=='9a99993e' and constants[2]['bytes']=='9a99193f'
def water_select(camera,verts):
    selected=[0.0,0.0,0.0];best=constants[0]['float32'];trace=[]
    for k in range(len(verts)-1,-1,-1):
        d=sum((camera[i]-selected[i])**2 for i in range(3));take=d<best
        trace.append({'candidate_index':k,'candidate':verts[k],'distance_tested_from_previous_selected':d,'selected_before':selected.copy(),'best_before':best,'accepted':take})
        if take:selected=verts[k].copy();best=d
    return {'selected':selected,'stored_best_distance_squared':best,'trace':trace}
wrong=water_select([10,0,0],[[0,0,0],[9,0,0],[100,0,0]])
assert wrong['selected']==[100,0,0]
assert water_select([10,0,0],[])['selected']==[0,0,0]
assert water_select([math.inf,0,0],[[1,0,0]])['selected']==[0,0,0]
result={'source':str(target),'sha256':hashlib.sha256(data).hexdigest(),'image_base':hex(base),'provenance':'Independent PE byte / Capstone evidence; not new REA Evidence or runtime reachability proof','constants':constants,'windows':windows,'water_sound':{'stack_mapping':{'camera_xyz':'ebp-0x34,-0x30,-0x2c','selected_for_distance_xyz':'ebp-0x28,-0x24,-0x20','current_candidate_xy':'ebp-0x1c,-0x18','current_candidate_z':'EDI','output_selected_xy':'ebp-0x14,-0x10','output_selected_z':'ebp-0x8 / EDI','best_distance_squared':'ebp-0x4'},'formula':'selected=(0,0,0);best=float.MaxValue;for i=verts.Count-1..0: candidate=verts[i];d2=SquaredMagnitude(camera-selected);if d2<best:selected=candidate;best=d2;transform.position=selected','conclusion':'The current candidate does not feed the squared distance. This is a one-item-lag selection defect in the shipped binary, not a decompiler error and not nearest-point selection.','no_selection':'Empty list, or all distance comparisons failing (NaN/overflow/infinite or >=float.MaxValue), leaves output zero. Missing camera/master/sandbanker/verts/component throws null-reference; it does not silently retain the previous frame position.','reference_counterexample':wrong},'sandbank_stage2':{'guard':'Outer pass==0; after cyclic rotation iA%2==1 and iB%2==1 and iC%2==0; A.y>0 or B.y>0; higher-priority A.y==0 && B.y==0 && C.y>0 branch is tested first. No distance comparison, clamp, nearest-neighbor search or C.y test is added to this correction branch.','source_vectors':'A=verts[iA], B=verts[iB], C=verts[iC] from current triangle; u=(B-A) with u.y=0; normal=Normalize((u.z,0,-u.x)); point-vector=C-A.','formula':'d=Dot(C-A,normal); delta=0.6*(0.3-d)*normal; displacement[iC/2]+=delta','target':'Only C even-index carrier at vertex index iC receives this correction after accumulating the triangle sweep. A and B are not moved by this branch.','normalization':'If length((u.z,0,-u.x))>float32 threshold, divide by that length; otherwise Vector3.zero. For a degenerate/very short horizontal edge normal is zero and this branch adds zero.','iteration':'Triangles visited backwards in triples. When neither branch matches, both indices and positions rotate A,B,C→B,C,A, up to three orientations. A matching branch stops that triangle rotation. After each outer pass apply displacement[k] to verts[2*k] and reset displacement[k] to zero; outer pass repeats three times, but this 0.3/0.6 correction is enabled only for pass0.','interpretation':'Horizontal signed point-to-directed-edge distance target0.3 with relaxation0.6. If d<0.3 push +normal; if d>0.3 pull -normal; d==0.3 zero correction. It is not Euclidean endpoint distance or a proximity cutoff.'},'limits':['Static formula/guard recovery, not exhaustive runtime scenario coverage. Reference WaterSound trace proves formula behavior for the listed fixture, not all inputs. Stage2 other branch and unrelated six-round smooth/stage3 behavior are handled in other reports.']}
result['vector_inequality']={'rva':'0x674620','formula':'For finite values: Vector3.op_Inequality(a,b) = ((a-b).sqrMagnitude >= float32(0x2edbe6ff)). COMISS threshold,squaredDistance followed SETBE also yields true for unordered/NaN.','threshold_va':'0x111d3a88','threshold_float32':constants[-1]['float32'],'threshold_bytes':constants[-1]['bytes']}
result['vector_inequality']['formula']=result['vector_inequality']['formula'].replace('0x2edbe6ff',hex(struct.unpack('<I',bytes.fromhex(constants[-1]['bytes']))[0]))
va=0x111f1650;off=pe.get_offset_from_rva(va-base);raw=data[off:off+4]
result['constants'].append({'va':hex(va),'meaning':'Stage2 odd vertex vertical lift before strip repair','bytes':raw.hex(),'float32':struct.unpack('<f',raw)[0]})
result['sandbank_stage2']['zero_height_endpoints']={'guard':'A.y==0 && B.y==0 && C.y>0, checked before the pass0 near-edge rule, on all three outer passes and all three cyclic orientations.','formula':'u=SetY(B-A,0);delta=0.3*u; if iA%2==0:displacement[iA/2]+=delta; if iB%2==0:displacement[iB/2]-=delta; then finish this triangle.','target':'A and B are independently eligible only when even indexed. C is unchanged by this rule. Displacement accumulates until end-of-pass flush to verts[2*k].','limits':'No normalization, projection onto another vector, sign test, clamped length, distance threshold, or C index parity guard. Edge length scales the displacement: a length2 edge yields magnitude0.6 at each eligible endpoint.','raw_bindings':{'guard':'0x10818920..0x10818950','B_minus_A':'0x10818a64','zero_y':'0x10818ac3','multiply03':'0x10818b00..0x10818b44','A_even_check':'0x10818b4c..0x10818b5b','add_to_A_slot':'0x10818bbe / 0x10818be3','B_even_check':'0x10818bf3..0x10818c02','subtract_from_B_slot':'0x10818c65 / 0x10818f0a'}}
result['strip_repair']={'iteration':'After six-round smoothing, lift every odd vertex by 0.186*Vector3.up, then scan triangle index groups backwards six indices per strip. Read iA=T[s],iB=T[s+1],iC=T[s+2],iD=T[s+4] and snapshot A/B/C/D coordinates.','original_triangles':'(iA,iB,iC),(iC,iD,iA), established by the six List.Add operations in Iterate stage1.','flags':'fA=Dot(D-A,savedNormalized[iA/2])<0; fB=Dot(C-B,savedNormalized[iB/2])<0. SavedNormalized is the separate local_58 list populated by the smoothing setup, not the fresh Cross result.','unused_cross':'The original executes Cross(Vector3.up,SetY(C-D,0)) at0x1081815b into stack buffer ebp-0x4a8, then immediately reads savedNormalized[iA/2]. No later instruction in the strip block reads that Cross buffer. The flags do not perform a segment-crossing test using this result.','flip_rule':'if (!fA && fB) flip unconditionally; if (fA && fB) flip only when SquaredMagnitude(B-D)<SquaredMagnitude(A-C); all other cases retain original triangles. Strict comparison includes full xyz.','flipped_indices':'T[s:s+6]=(iA,iB,iD,iC,iD,iB), i.e. triangles(A,B,D),(C,D,B), sharing B-D.','vertex_collapse_cases':[{'fA':False,'fB':False,'triangles':'unchanged','writes':['verts[iA]=SetY(D,0)','verts[iB]=SetY(C,0)','verts[iC]=SetY(C,0)','verts[iD]=SetY(D,0)']},{'fA':False,'fB':True,'triangles':'unconditionally flipped','writes':['verts[iD]=SetY(D,0)','verts[iA]=SetY(D,0)']},{'fA':True,'fB':False,'triangles':'unchanged','writes':['verts[iC]=SetY(C,0)','verts[iB]=SetY(C,0)']},{'fA':True,'fB':True,'triangles':'flipped only if B-D shorter than A-C','writes':[]}],'raw_bindings':{'odd_lift':'0x10817cfd..0x10817e24','iA':'ebp-0x50','iB':'ebp-0xa4','iC':'ebp-0x34','iD':'ebp-0x44','fA_dot_compare':'0x10818213..0x1081825e','fB_dot_compare':'0x108182fc..0x10818334','four_way_dispatch':'0x10818337..0x10818349','forced_flip_six_writes':['0x10818454','0x10818479','0x10818499','0x108184bc','0x108184dc','0x10818503'],'shorter_test':'0x10818634 / 0x10818657 (A-C),0x10818699 / 0x108186bc (B-D),0x108186cc / 0x108186d0 (strict compare)','shorter_flip_six_writes':['0x108186ee','0x10818713','0x10818733','0x10818756','0x10818776','0x1081879d']},'conclusion':'This block includes directional endpoint collapse and unconditional topology repair. Only the both-negative flag case prefers the shorter diagonal, so describing the entire block as shortest-diagonal selection omits behavior.'}
result['limits'][-1]='Six-round smoothing, the later triangle height-cap rules and stage3 are handled in corresponding reports; this artifact now includes both three-pass local branches and strip collapse/diagonal selection.'
(BASE/'outputs/townscaper_shore_local_math.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
print(json.dumps({'raw_windows':len(windows),'raw_instructions':sum(len(w['instructions'])for w in windows),'constants':constants,'water_counterexample_output':wrong['selected']}))
